function panel(q,id){const[w,h]=q.panels[id];return '<figure class="scsa-source-figure" style="margin:0 0 8px;break-inside:avoid"><a data-scsa-image-link="'+esc(q.imagePack+':'+id)+'" href="'+esc(q.sourceUrl)+'" target="_blank" rel="noopener"><img data-scsa-pack="'+esc(q.imagePack)+'" data-scsa-image="'+esc(id)+'" width="'+w+'" height="'+h+'" alt="'+esc(q.course+' '+q.examYear+' Question '+q.sourceQuestionNumber)+'" style="display:block;width:100%;height:auto" loading="lazy"></a></figure>'}
function question(q){let s='<div class="exam-source-layout"><p><strong>'+esc(q.examYear+' SCSA '+q.course+' — Question '+q.sourceQuestionNumber+' ('+q.marks+' '+(q.marks===1?'mark':'marks')+')')+'</strong></p>'+q.imageIds.map(id=>panel(q,id)).join('');if(q.supportImageIds.length)s+='<details class="scsa-support-booklet" data-scsa-support="'+esc(q.imagePack)+'"><summary>Supporting source booklet — use the source specified in this question</summary>'+q.supportImageIds.map(id=>panel(q,id)).join('')+'</details>';if(q.type==='Multiple Choice')s+='<p>Answer: __________</p>';else if(q.extraLines)s+='<div class="scsa-extra-writing">'+Array.from({length:q.extraLines},()=>'<div style="height:24px;border-bottom:1px solid #aaa"></div>').join('')+'</div>';return s+'<p>Original examination diagrams and writing spaces retained. Check suitability against your teaching syllabus.</p></div>'}
const bank=window.UpperSchoolQuestionBank=window.UpperSchoolQuestionBank||[],ids=new Set(bank.map(q=>q.id));
